import re
from decimal import Decimal, ROUND_HALF_UP

_UNIT_SECONDS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
    "w": 604800, "wk": 604800, "wks": 604800, "week": 604800, "weeks": 604800,
}

_NUM = r"\d+(?:\.\d+)?"
_UNIT_ALT = "|".join(sorted(_UNIT_SECONDS, key=len, reverse=True))

_BARE_INT = re.compile(r"\d+")
_COMPONENT = re.compile(
    r"(%s)\s*(%s)(?![a-z])" % (_NUM, _UNIT_ALT), re.IGNORECASE
)
_FREEFORM = re.compile(
    r"(?:\s*%s\s*(?:%s)(?![a-z]))+\s*" % (_NUM, _UNIT_ALT), re.IGNORECASE
)
_ISO = re.compile(
    r"P(?=\d|T\d)"
    r"(?:(%(n)s)W)?"
    r"(?:(%(n)s)D)?"
    r"(?:T(?=\d)(?:(%(n)s)H)?(?:(%(n)s)M)?(?:(%(n)s)S)?)?"
    r"" % {"n": _NUM},
    re.IGNORECASE,
)
_ISO_FULL_CHECK = re.compile(r"P.*")
_CLOCK = re.compile(r"(\d+):(\d+)(?::(\d+))?")


def _to_seconds(number: str, unit_seconds: int) -> Decimal:
    return Decimal(number) * unit_seconds


def _round(total: Decimal) -> int:
    return int(total.quantize(Decimal(1), rounding=ROUND_HALF_UP))


def _parse_iso(text: str) -> int:
    m = _ISO.fullmatch(text)
    if not m:
        raise ValueError(f"invalid ISO 8601 duration: {text!r}")
    weeks, days, hours, minutes, seconds = m.groups()
    if all(g is None for g in m.groups()):
        raise ValueError(f"empty ISO 8601 duration: {text!r}")
    total = Decimal(0)
    for value, unit in (
        (weeks, 604800), (days, 86400), (hours, 3600),
        (minutes, 60), (seconds, 1),
    ):
        if value is not None:
            total += _to_seconds(value, unit)
    return _round(total)


def _parse_clock(text: str) -> int:
    m = _CLOCK.fullmatch(text)
    if not m:
        raise ValueError(f"invalid clock duration: {text!r}")
    if m.group(3) is None:
        minutes, seconds = int(m.group(1)), int(m.group(2))
        return minutes * 60 + seconds
    hours, minutes, seconds = int(m.group(1)), int(m.group(2)), int(m.group(3))
    if minutes >= 60 or seconds >= 60:
        raise ValueError(f"out-of-range clock duration: {text!r}")
    return hours * 3600 + minutes * 60 + seconds


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    if _BARE_INT.fullmatch(s):
        return int(s)

    if s[0] in "Pp":
        return _parse_iso(s.upper())

    if ":" in s:
        return _parse_clock(s)

    if not _FREEFORM.fullmatch(s):
        raise ValueError(f"invalid duration: {text!r}")

    total = Decimal(0)
    for number, unit in _COMPONENT.findall(s):
        total += _to_seconds(number, _UNIT_SECONDS[unit.lower()])
    return _round(total)

